mapper.select:
SELECT EXISTS(
    SELECT 1
    FROM lambda_async_submission_outbox
    WHERE lambda_assignment_id = #{lambdaAssignmentId}
      AND run_id = #{runId}
)

mapper.insert:
INSERT INTO lambda_async_submission_outbox (
    lambda_assignment_id, run_id, payload, retry_at, last_error
) VALUES (
    #{lambdaAssignmentId}, #{runId}, #{payload}, #{retryAt}, #{lastError}
)

mapper.delete:
DELETE FROM lambda_async_submission_outbox
WHERE lambda_assignment_id = #{lambdaAssignmentId}
  AND run_id = #{runId}
  AND claim_id = #{claimId,typeHandler=dev.olegz.vf.registry.dao.handlers.UuidStringTypeHandler}

mapper.update:
UPDATE lambda_async_submission_outbox
SET retry_at = #{retryAt}, attempt_count = attempt_count + 1, last_error = #{lastError},
    claim_id = NULL, claim_until = NULL
WHERE lambda_assignment_id = #{lambdaAssignmentId}
  AND run_id = #{runId}
  AND claim_id = #{claimId,typeHandler=dev.olegz.vf.registry.dao.handlers.UuidStringTypeHandler}
